# Full four-clause form
try:
    result = int(user_input)          # might raise ValueError
except ValueError as e:
    print(f'Invalid number: {e}')     # runs on ValueError
except TypeError:
    print('Wrong type entirely')
else:
    print(f'Parsed successfully: {result}')  # runs only if no exception
finally:
    print('Always runs — cleanup here')

# Common pattern: file handling
try:
    f = open('data.txt')
except FileNotFoundError:
    print('File not found')
else:
    content = f.read()  # only runs if open() succeeded
    process(content)
finally:
    if 'f' in dir():    # check f was assigned
        f.close()

# Better: context manager handles finally automatically
try:
    with open('data.txt') as f:
        content = f.read()
except FileNotFoundError:
    content = ''

# Re-raising with context
try:
    risky_operation()
except DatabaseError as e:
    logger.error('DB failed', exc_info=True)
    raise ServiceUnavailableError('Upstream DB down') from e  # chaining

# Base exception for your package
class AppError(Exception):
    """Base exception for the payments package."""
    pass

# Specific subtypes
class ValidationError(AppError):
    def __init__(self, field: str, value, message: str):
        self.field = field
        self.value = value
        super().__init__(f"Validation failed on '{field}': {message}")

class PaymentGatewayError(AppError):
    def __init__(self, gateway: str, status_code: int, detail: str):
        self.gateway = gateway
        self.status_code = status_code
        super().__init__(f"{gateway} returned {status_code}: {detail}")

class InsufficientFundsError(PaymentGatewayError):
    def __init__(self, amount: float, balance: float):
        self.amount = amount
        self.balance = balance
        super().__init__('stripe', 402, f'Need {amount}, have {balance}')

# Usage — caller can catch at right level
try:
    process_payment(amount=100.0, balance=50.0)
except InsufficientFundsError as e:
    # Structured data available
    notify_user(f'You need ${e.amount - e.balance:.2f} more')
except PaymentGatewayError as e:
    # Catches InsufficientFundsError too if not caught above
    log_gateway_failure(e.gateway, e.status_code)
except AppError:
    # Broad catch — any error from this package
    return error_response('Payment system unavailable')
